package com.alpharip.staffmod.cases.caseredactiontool; import net.minecraft.client.gui.*;import java.io.IOException;import java.util.*; public final class CaseRedactionToolGui extends GuiScreen {private final GuiScreen parent;private final CaseRedactionTool module;private GuiTextField id,title,source,start,end,reason;private String selected="",notice="";public CaseRedactionToolGui(GuiScreen p,CaseRedactionTool m){parent=p;module=m;}public void initGui(){buttonList.clear();int x=Math.max(8,width/2-210);id=new GuiTextField(1,fontRendererObj,x,38,95,18);title=new GuiTextField(2,fontRendererObj,x+100,38,315,18);source=new GuiTextField(3,fontRendererObj,x,78,415,18);start=new GuiTextField(4,fontRendererObj,x,118,55,18);end=new GuiTextField(5,fontRendererObj,x+60,118,55,18);reason=new GuiTextField(6,fontRendererObj,x+120,118,235,18);for(GuiTextField f:fields())f.setMaxStringLength(240);buttonList.add(new GuiButton(1,x+360,117,55,20,"Add range"));buttonList.add(new GuiButton(2,x,height-28,75,20,"Add doc"));buttonList.add(new GuiButton(3,x+80,height-28,75,20,"Save"));buttonList.add(new GuiButton(4,x+160,height-28,75,20,"Close"));}private List<GuiTextField> fields(){return Arrays.asList(id,title,source,start,end,reason);}protected void actionPerformed(GuiButton b)throws IOException{if(b.id==4){mc.displayGuiScreen(parent);return;}if(b.id==2){try{RedactionDocument d=new RedactionDocument(id.getText(),title.getText(),source.getText(),Collections.<RedactionEntry>emptyList());if(!module.getService().add(d))throw new IllegalArgumentException();selected=d.getId();notice="Document added.";}catch(Exception e){notice="Enter a unique ID, title and source.";}}if(b.id==1){try{RedactionDocument d=module.getService().get(selected);if(d==null)throw new IllegalArgumentException();module.getService().replace(d.add(new RedactionEntry(Integer.parseInt(start.getText()),Integer.parseInt(end.getText()),reason.getText(),true)));notice="Range added.";}catch(Exception e){notice="Select a document and enter valid character offsets.";}}if(b.id==3)notice=module.save()?"Saved locally.":"Save failed.";}protected void keyTyped(char c,int k)throws IOException{for(GuiTextField f:fields())f.textboxKeyTyped(c,k);super.keyTyped(c,k);}protected void mouseClicked(int x,int y,int b)throws IOException{super.mouseClicked(x,y,b);for(GuiTextField f:fields())f.mouseClicked(x,y,b);if(y>=205&&y<height-45){int i=(y-205)/12;List<RedactionDocument> ds=module.getService().getDocuments();if(i>=0&&i<ds.size())selected=ds.get(i).getId();}}public void updateScreen(){for(GuiTextField f:fields())f.updateCursorCounter();}public void drawScreen(int mx,int my,float pt){drawDefaultBackground();int x=Math.max(8,width/2-210);drawCenteredString(fontRendererObj,"CASE REDACTION TOOL",width/2,15,0xFFFFC83D);drawString(fontRendererObj,"Document ID / title",x,27,0xFFFFFF);drawRect(x,38,x+96,57,0xAA20242C);drawRect(x+99,38,x+416,57,0xAA20242C);id.drawTextBox();title.drawTextBox();drawString(fontRendererObj,"Source text (single-line field in this prototype)",x,65,0xFFFFFF);drawRect(x,78,x+416,97,0xAA20242C);source.drawTextBox();drawString(fontRendererObj,"Start / End / Reason",x,105,0xFFFFFF);drawRect(x,118,x+56,137,0xAA20242C);drawRect(x+60,118,x+116,137,0xAA20242C);drawRect(x+120,118,x+356,137,0xAA20242C);start.drawTextBox();end.drawTextBox();reason.drawTextBox();RedactionDocument d=module.getService().get(selected);if(d!=null)drawString(fontRendererObj,"PREVIEW: "+fontRendererObj.trimStringToWidth(d.renderRedacted(),width-30),x,155,0xFFE5E7EB);int y=205;for(RedactionDocument doc:module.getService().getDocuments()){drawString(fontRendererObj,(doc.getId().equals(selected)?"> ":"  ")+doc.getId()+" - "+doc.getTitle(),x,y,0xFFFFFFFF);y+=12;if(y>height-48)break;}if(!notice.isEmpty())drawCenteredString(fontRendererObj,notice,width/2,height-43,0xFFFFC83D);super.drawScreen(mx,my,pt);}public boolean doesGuiPauseGame(){return false;}}